use bennett_isa_ref::{Object,ClassicalMachine};fn main(){let a:Vec<_>=std::env::args().collect();let o=Object::parse(&std::fs::read_to_string(&a[1]).unwrap()).unwrap();o.check_hashes().unwrap();let mut m=ClassicalMachine::new(&o,"f",&[],&[]).unwrap();let entry=m.snapshot();m.run(3).unwrap();{let reply=vec![1;1048576];m.reply(&reply).unwrap();}m.step_once().unwrap();let before=m.snapshot();println!("parse/hash OK; request+reply+v complete; frames={} byte={:?}",m.outcome().steps,m.memory_bytes(1,1).unwrap());let result=m.step_once();println!("store_result={result:?}; prefix_equal={}; difference={:?}; frames={}",before==m.snapshot(),before.first_difference(&m.snapshot()),m.outcome().steps);drop(before);let next=m.step_once().unwrap().unwrap();println!("after releasing observer next_op={}",next.instruction.op);let out=m.run(3).unwrap();println!("completed_result={:?}; byte={:?}; fault={:?}",out.values[0],m.memory_bytes(1,1).unwrap(),out.fault);m.reverse().unwrap();println!("reversed_to_entry={}",entry==m.snapshot());}